$catalog$::jsonb) as seed(category text,brand text,name text,variant text,aliases text,specs jsonb,source_url text)
on conflict (category,lower(trim(brand)),lower(trim(name)),lower(trim(variant))) do update
set specs=excluded.specs||current.specs,
 source_url=case when current.source_url='' then excluded.source_url else current.source_url end,
 aliases=case when current.aliases='' then excluded.aliases else current.aliases end,
 updated_at=clock_timestamp()
where current.specs is distinct from excluded.specs||current.specs or current.source_url='' or (current.aliases='' and excluded.aliases<>'');
